fun qiymetlendir(bal: Int): String = when {
    bal >= 90 -> "Əla"
    bal >= 70 -> "Yaxşı"
    bal >= 50 -> "Qənaətbəxş"
    else -> "Kafi deyil"
}

fun main() {
    for (bal in listOf(95, 75, 55, 30)) {
        println("$bal -> ${qiymetlendir(bal)}")
    }
}

