fun salamla(ad: String = "Dünya", boyuk: Boolean = false): String {
    val metn = "Salam, $ad!"
    return if (boyuk) metn.uppercase() else metn
}

fun kvadrat(x: Int) = x * x

fun main() {
    println(salamla())
    println(salamla("Aysel"))
    println(salamla("Kamran", boyuk = true))
    println(kvadrat(7))
}

